using System; using System.Configuration; using System.IO; using System.Web; using BabcoUnloadCompare.Web.Services;
namespace BabcoUnloadCompare.Web.Handlers { public class DocumentDownload:IHttpHandler { public bool IsReusable=>false; public void ProcessRequest(HttpContext c){int id;if(!int.TryParse(c.Request.QueryString["id"],out id)){c.Response.StatusCode=400;return;}var d=new DataAccess().GetDocumentPath(id);if(d==null){c.Response.StatusCode=404;return;}var root=c.Server.MapPath(ConfigurationManager.AppSettings["UnloadCompare.UploadRoot"]);string found=null;foreach(var dir in Directory.GetDirectories(root)){var p=Path.Combine(dir,d.Item1);if(File.Exists(p)){found=p;break;}}if(found==null){c.Response.StatusCode=404;return;}c.Response.ContentType=string.IsNullOrWhiteSpace(d.Item3)?"application/octet-stream":d.Item3;c.Response.AddHeader("Content-Disposition","attachment; filename=\""+d.Item2.Replace("\"","")+"\"");c.Response.TransmitFile(found);} } }
